"""Small additive panel for campaign-based public prospect discovery."""

# ruff: noqa: E501 - embedded dashboard assets.
PANEL = """<section class="panel" id="publicDiscoveryPanel">
<div class="view-heading"><h2>Public-web prospects</h2><p>Campaign search → public evidence checks → duplicate removal → strongest matches first. No LinkedIn login or worker required. These are research prospects, not verified customers.</p></div>
<div class="toolbar"><label for="publicTarget">Target prospects</label><input id="publicTarget" type="number" min="1" max="100" value="60" style="width:90px;padding:10px;border:1px solid #d0d5dd;border-radius:8px"><button class="btn primary" type="button" id="publicDiscover" disabled>Discover public profiles</button><button class="btn" type="button" id="publicRefresh">Refresh</button><a class="btn" id="publicExport" hidden>Download public prospects CSV</a></div>
<div class="toolbar"><label for="publicRequestBudget">Maximum API requests this run</label><input id="publicRequestBudget" type="number" min="1" max="25" value="5" style="width:90px;padding:10px;border:1px solid #d0d5dd;border-radius:8px"><span>Shared cap for discovery and automatic public-detail checks. Start with 5; incomplete fields may remain when the cap is used.</span></div>
<p class="view-status" id="publicUsage" role="status"></p><p class="view-status"><a href="https://api-dashboard.search.brave.com/app/credits" target="_blank" rel="noopener noreferrer">Check actual Brave credits / auto-reload ↗</a></p>
<p class="view-status" id="publicReadiness" role="status">Checking public discovery…</p><p class="view-status" id="publicProgress" role="status"></p>
<div class="toolbar"><label for="publicEvidenceFilter">Evidence review</label><select id="publicEvidenceFilter"><option value="all">All prospects</option><option value="matched">Required evidence matched</option><option value="missing">Needs verification</option></select></div><p class="view-status" id="publicEvidenceSummary" role="status"></p>
<div class="toolbar"><button class="btn" id="publicSyncPipeline" type="button" hidden>Sync to pipeline / reports</button><button class="btn" id="publicSelectEligible" type="button" hidden>Select prospects for review</button><button class="btn primary" id="publicSaveLeads" type="button" hidden disabled>Save selected for review</button></div><p class="view-status" id="publicSaveStatus" role="status">Completed stored searches add all prospects to Collected profiles, Saved leads for review and Reports. Scores use the existing qualification rules. Incomplete prospects keep their missing-evidence reasons and need verification. Nothing is auto-approved or sent.</p>
<div class="table-wrap" style="max-height:440px;overflow:auto"><table><thead><tr><th>Select</th><th>Name / public title</th><th>Public evidence</th><th>Review</th><th>Source</th></tr></thead><tbody id="publicRows"></tbody></table></div>
<p class="view-status">Powered by <a href="https://brave.com/search/api/" target="_blank" rel="noopener noreferrer">Brave Search API</a>. Target is a maximum, not a guaranteed number of matches. Up to 25 search requests per run; discovery may continue after reaching the target to replace incomplete matches with stronger evidence. Repetitive results stop early. Public snippets may be incomplete or outdated. Existing lead review, connection and message workflows are unchanged. Discovery never sends outreach.</p>
</section>"""

SCRIPT = r"""<script>
(()=>{
const el=id=>document.getElementById(id);let ready=false,busy=false,posting=false,lastJob=null,saving=false;const selected=new Set();
function saveButtons(){const allowed=!!lastJob?.persistent&&lastJob.status!=='running';el('publicSaveLeads').hidden=el('publicSelectEligible').hidden=!allowed;el('publicSyncPipeline').hidden=!lastJob?.persistent||lastJob.status!=='completed';el('publicSyncPipeline').disabled=saving;el('publicSaveLeads').disabled=!allowed||saving||!selected.size;el('publicSelectEligible').disabled=saving;el('publicSaveLeads').textContent=`Save selected for review (${selected.size})`;}
function paint(job){if(job?.id!==lastJob?.id){selected.clear();el('publicSaveStatus').textContent='Save only after reviewing public evidence. Saving never approves a lead or authorizes sending.';}lastJob=job;saveButtons();const rows=el('publicRows');rows.replaceChildren();el('publicExport').hidden=!job?.found||!job?.persistent;
if(!job){el('publicProgress').textContent='No public discovery run yet.';el('publicEvidenceSummary').textContent='';busy=false;return;}
busy=job.status==='running';el('publicProgress').textContent=`${job.name}: ${job.found}/${job.target} unique public prospects · ${job.api_calls}/${job.max_requests||25} search requests · ${job.status}. ${job.persistent?'':('Temporary preview only'+(job.expires_at?' until '+new Date(job.expires_at*1000).toLocaleTimeString():'')+'. ')}${job.message||''}`;
const results=job.results||[],matched=results.filter(item=>!(item.missing||[]).length).length;
const different=el('searchCampaign')?.value&&el('searchCampaign').value!==job.campaign;
el('publicEvidenceSummary').textContent=`${matched} with required public evidence · ${results.length-matched} need verification. ${job.pipeline_synced?'Synced to Collected profiles, Saved leads and Reports. ':''}These counts do not confirm current employment or buying intent.${different?' Showing the previous campaign run. Start discovery to search the newly selected campaign.':''}`;
el('publicExport').href='/api/public-discovery/jobs/'+encodeURIComponent(job.id)+'/export.csv';
const filter=el('publicEvidenceFilter').value;
for(const item of results){const missing=item.missing||[];if(filter==='matched'&&missing.length||filter==='missing'&&!missing.length)continue;const tr=document.createElement('tr'),pick=document.createElement('td'),check=document.createElement('input');check.type='checkbox';check.disabled=!job.persistent||busy||saving;check.checked=selected.has(item.profile_url);check.setAttribute('aria-label','Select '+item.name+' for manual review');check.title=missing.length?'Save with missing evidence to Needs verification; no approval or sending.':'Save for review';check.onchange=()=>{check.checked?selected.add(item.profile_url):selected.delete(item.profile_url);saveButtons();};pick.append(check);tr.append(pick);for(const value of [item.name+' — '+item.public_title,item.snippet,item.review_status+' · Matched: '+((item.matched||[]).join(', ')||'None')+(missing.length?' · Missing evidence: '+missing.join(', '):'')]){const td=document.createElement('td');td.textContent=value;tr.append(td);}const info=item.profile_details;if(info){const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='Available profile details (public, unverified)';details.append(summary);if(item.automatic_detail_check){const status=document.createElement('p');status.textContent=item.automatic_detail_check;details.append(status);}for(const key of ['location','current_role','company','industry','about','experience','education','skills','connections','followers']){const line=document.createElement('div'),value=info[key];line.textContent=key.replaceAll('_',' ')+': '+(Array.isArray(value)?value.join(' | ')||'Not available':value||'Not available');details.append(line);}tr.children[2].append(details);}const td=document.createElement('td'),a=document.createElement('a');a.textContent='Public LinkedIn URL ↗';a.href=item.profile_url;a.target='_blank';a.rel='noopener noreferrer';td.append(a);tr.append(td);rows.append(tr);}
if(!rows.children.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=5;td.textContent='No prospects in this evidence filter.';tr.append(td);rows.append(tr);}}
function buttons(){el('publicDiscover').disabled=!ready||busy||posting||!el('searchCampaign')?.value;}
async function refresh(){try{const r=await fetch('/api/public-discovery/settings');if(!r.ok)throw Error('Cannot load public discovery settings.');const data=await r.json();ready=data.configured;el('publicReadiness').textContent=data.message;const usage=data.usage;el('publicUsage').textContent=usage?`${usage.month_attempts} attempted requests this month (${usage.month_utc}, UTC) · ${usage.total_attempts} total tracked. ${usage.scope} Failed attempts may not be billed; historical and other-app usage is not included.`:'';paint(data.job);}catch(error){ready=false;el('publicReadiness').textContent=error.message;}buttons();}
el('publicRefresh').onclick=refresh;el('publicEvidenceFilter').onchange=()=>paint(lastJob);el('searchCampaign')?.addEventListener('change',()=>{paint(lastJob);buttons();});
el('publicSelectEligible').onclick=()=>{for(const item of lastJob?.results||[]){selected.add(item.profile_url);}paint(lastJob);};
el('publicSyncPipeline').onclick=async()=>{if(!lastJob||saving)return;saving=true;saveButtons();try{const r=await fetch('/api/public-discovery/jobs/'+encodeURIComponent(lastJob.id)+'/sync-pipeline',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});const data=await r.json();if(!r.ok)throw Error(typeof data.detail==='string'?data.detail:'Pipeline sync failed.');el('publicSaveStatus').textContent=`${data.collected} collected profiles · ${data.saved_leads} saved for verification · ${data.inserted} newly added. Available in review and reports. Nothing approved or sent.`;if(typeof load==='function')await load();if(typeof loadSummary==='function')await loadSummary();if(typeof loadObservationRuns==='function')await loadObservationRuns();if(typeof loadObservations==='function')await loadObservations();await refresh();}catch(error){el('publicSaveStatus').textContent=error.message;}finally{saving=false;saveButtons();}};
el('publicSaveLeads').onclick=async()=>{if(!lastJob||!selected.size||saving)return;saving=true;paint(lastJob);try{const r=await fetch('/api/public-discovery/jobs/'+encodeURIComponent(lastJob.id)+'/save-leads',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({profile_urls:[...selected]})});const data=await r.json();if(!r.ok)throw Error(typeof data.detail==='string'?data.detail:'Unable to save prospects.');el('publicSaveStatus').textContent=`${data.inserted} saved for review; ${data.skipped} already saved from this discovery. Open Saved leads for review, verify details, then use existing outreach approval. Nothing sent.`;selected.clear();if(typeof load==='function')await load();if(typeof loadSummary==='function')await loadSummary();}catch(error){el('publicSaveStatus').textContent=error.message;}finally{saving=false;paint(lastJob);}};
el('publicDiscover').onclick=async()=>{posting=true;buttons();try{const target=Number(el('publicTarget').value),max_requests=Number(el('publicRequestBudget').value);if(!Number.isInteger(target)||target<1||target>100)throw Error('Choose a target from 1 to 100.');if(!Number.isInteger(max_requests)||max_requests<1||max_requests>25)throw Error('Choose an API request cap from 1 to 25.');const r=await fetch('/api/public-discovery/jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({campaign:el('searchCampaign').value,target,max_requests})});const data=await r.json();if(!r.ok)throw Error(typeof data.detail==='string'?data.detail:'Check the campaign and target.');paint(data);}catch(error){el('publicProgress').textContent=error.message;}finally{posting=false;buttons();}};
refresh();setInterval(()=>{if(busy||(lastJob?.expires_at&&Date.now()/1000>=lastJob.expires_at))refresh();},5000);
})();
</script>"""
